"""Join directed Section cubics into a native continuous Bundle member.

Copies exact control points and handles, not evaluated samples. At a shared
Section endpoint the outgoing Section owns the point and its outgoing handle;
the incoming handle is retained from the preceding Section. Thus each original
cubic span is unchanged. Source Section identity remains on each outgoing span.
"""
from . import interpolating_curve_nodes, bundle_dimension_nodes


POINT_FIELDS = {'st_curve_handle_left': 'FLOAT_VECTOR',
                'st_curve_handle_right': 'FLOAT_VECTOR',
                'st_poly_miter': 'FLOAT_VECTOR'}


def merge(g, selected):
    """Return one directed curve, validity and original Section span IDs.

    Input CURVE fields: st_chain_order, st_chain_forward, st_sweep_id,
    st_sweep_width/offset/rise/datum/interpolation/valid. Sort order is explicit;
    input datablock order and spatial proximity do not establish ownership.
    """
    index = g.node('GeometryNodeInputIndex', 'Section or control index').outputs[0]
    pos = g.node('GeometryNodeInputPosition', 'Exact Section control point').outputs[0]
    ordered = g.node('GeometryNodeSortElements', 'Semantic Section traversal order')
    ordered.domain = 'CURVE'; g.set(selected, ordered.inputs['Geometry'])
    g.set(g.named('st_chain_order', 'INT'), ordered.inputs['Sort Weight'])
    original = ordered.outputs['Geometry']
    backward = g.boolean('NOT', g.named('st_chain_forward', 'BOOLEAN'))
    oriented = original
    # Explicit attribute sampling prevents one Store from changing a later
    # field's source during the handle swap.
    for name in POINT_FIELDS:
        field = g.named(name, 'FLOAT_VECTOR')
        if name.endswith('left'):
            reverse_value = g.named('st_curve_handle_right', 'FLOAT_VECTOR')
        elif name.endswith('right'):
            reverse_value = g.named('st_curve_handle_left', 'FLOAT_VECTOR')
        else:
            reverse_value = g.vector('SCALE', field, -1.)
        value = g.sample(original, g.switch(backward, field, reverse_value, 'VECTOR'), index, 'FLOAT_VECTOR')
        oriented = g.store(oriented, name, value, 'FLOAT_VECTOR')
    for name, value in (('offset', g.switch(backward, g.named('st_sweep_offset','FLOAT'),
                                          g.math('MULTIPLY', -1., g.named('st_sweep_offset','FLOAT')))),
                        ('inner_u', g.switch(backward, g.named('st_sweep_inner_u','FLOAT'),
                                            g.math('SUBTRACT', 1., g.named('st_sweep_inner_u','FLOAT'))))):
        oriented = g.store(oriented, 'st_sweep_'+name,
                           g.sample(original,value,index,'FLOAT','CURVE'),'FLOAT','CURVE')
    reverse = g.node('GeometryNodeReverseCurve', 'Follow each authored Section direction explicitly')
    g.set(oriented, reverse.inputs['Curve']); g.set(backward, reverse.inputs['Selection'])
    oriented = reverse.outputs['Curve']
    oriented = bundle_dimension_nodes.prepare(g, oriented)
    size = g.node('GeometryNodeAttributeDomainSize', 'All Section control points')
    size.component = 'CURVE'; g.set(oriented, size.inputs['Geometry'])
    n, ns = size.outputs['Point Count'], size.outputs['Spline Count']
    owner = g.node('GeometryNodeCurveOfPoint', 'Section ownership of each original control')
    g.set(index, owner.inputs['Point Index'])
    curve_index = g.sample(oriented, owner.outputs['Curve Index'], index)
    local_index = g.sample(oriented, owner.outputs['Index in Curve'], index)
    next_owner = g.sample(oriented, owner.outputs['Curve Index'], g.math('MINIMUM',
        g.math('SUBTRACT',n,1.),g.math('ADD',index,1.)))
    duplicate = g.compare(next_owner, curve_index, 'NOT_EQUAL', 'INT')
    join_start = g.all(g.compare(local_index,0,kind='INT'),g.compare(curve_index,0,'GREATER_THAN','INT'))
    points = g.node('GeometryNodePoints', 'Exact controls; no curve resampling')
    g.set(g.math('MINIMUM',n,1024), points.inputs['Count'])
    g.set(g.sample(oriented,pos,index,'FLOAT_VECTOR'),points.inputs['Position'])
    controls = points.outputs['Points']
    for name in POINT_FIELDS:
        source_index = g.switch(join_start,index,g.math('SUBTRACT',index,1.),'INT') if name.endswith('left') else index
        controls = g.store(controls,name,g.sample(oriented,g.named(name,'FLOAT_VECTOR'),
            source_index,'FLOAT_VECTOR'),'FLOAT_VECTOR')
    controls = g.store(controls,'st_chain_source_section',g.sample(oriented,
        g.named('st_sweep_id','INT'),curve_index,'INT','CURVE'),'INT')
    for name,kind in bundle_dimension_nodes.FIELDS.items():
        controls=g.store(controls,'st_span_'+name,g.sample(oriented,g.named('st_span_'+name,kind),
            curve_index,kind,'CURVE'),kind)
    seam_ok = g.either(g.boolean('NOT',join_start), g.compare(g.vector('DISTANCE',
        g.sample(oriented,pos,index,'FLOAT_VECTOR'),
        g.sample(oriented,pos,g.math('SUBTRACT',index,1.),'FLOAT_VECTOR')),1e-5,'LESS_EQUAL'))
    valid = g.all(g.compare(ns,1,'GREATER_EQUAL','INT'),g.compare(n,1024,'LESS_EQUAL','INT'),
                  g.stat(controls,seam_ok),g.stat(oriented,g.named('st_sweep_valid','BOOLEAN'),'CURVE'))
    valid=g.all(valid,g.stat(oriented,g.named('st_span_valid','BOOLEAN'),'CURVE'))
    for name, kind in (('rise','FLOAT'),('datum','FLOAT'),('interpolation','INT')):
        value=g.named('st_sweep_'+name,kind); first=g.sample(oriented,value,0,kind,'CURVE')
        valid=g.all(valid,g.stat(oriented,g.close(value,first,1e-7),'CURVE'))
    delete=g.node('GeometryNodeDeleteGeometry','Share Section endpoint identity once');delete.domain='POINT'
    g.set(controls,delete.inputs['Geometry']);g.set(duplicate,delete.inputs['Selection'])
    curve=g.node('GeometryNodePointsToCurves','One complete ordered member curve')
    g.set(delete.outputs['Geometry'],curve.inputs['Points']);g.set(index,curve.inputs['Weight'])
    polyline=curve.outputs['Curves']
    polyline=g.store(polyline,'st_knot_index',index,'INT')
    cubic=g.node('GeometryNodeCurveSplineType','Preserve cubic spans from their original handles');cubic.spline_type='BEZIER'
    g.set(polyline,cubic.inputs['Curve'])
    free=g.node('GeometryNodeCurveSetHandles','Exact FREE handles across Section boundaries')
    free.mode={'LEFT','RIGHT'};free.handle_type='FREE';g.set(cubic.outputs['Curve'],free.inputs['Curve'])
    result=free.outputs['Curve']
    for side in ('LEFT','RIGHT'):
        handles=g.node('GeometryNodeSetCurveHandlePositions','Preserved '+side.lower()+' handle');handles.mode=side
        g.set(result,handles.inputs['Curve']);g.set(g.named('st_curve_handle_'+side.lower(),'FLOAT_VECTOR'),handles.inputs['Position'])
        result=handles.outputs['Curve']
    resolution=g.node('GeometryNodeSetSplineResolution','Existing optimized cubic evaluation density')
    resolution.inputs['Resolution'].default_value=interpolating_curve_nodes.EVALUATION_RESOLUTION
    g.set(result,resolution.inputs['Curve']);result=resolution.outputs['Curve']
    mode=g.sample(oriented,g.named('st_sweep_interpolation'),0,'INT','CURVE')
    result=g.switch(g.compare(mode,3,kind='INT'),polyline,result,'GEOMETRY')
    result=g.store(result,'st_chain_valid',valid,'BOOLEAN','CURVE')
    return result,valid,oriented


def construct(g, curves):
    """Normalize only networks with an explicit multi-Section Bundle chain.

    Unchanged single-Section networks bypass this branch. Stable source IDs
    remain on each outgoing span; compact sweep indices are private lookups.
    """
    index = g.node('GeometryNodeInputIndex', 'Sweep chain index').outputs[0]
    pos = g.node('GeometryNodeInputPosition', 'Joined member control').outputs[0]
    enabled = g.stat(curves, g.named('st_chain_aggregate', 'BOOLEAN'), 'CURVE', output='Max')
    count = g.math('ADD', 1., g.stat(curves, g.named('st_chain_index'), 'CURVE', output='Max'))
    ri = g.node('GeometryNodeRepeatInput', 'One continuous sweep per complete Bundle member')
    ro = g.node('GeometryNodeRepeatOutput', 'Continuous members and unchanged ordinary Sections')
    ro.repeat_items.clear(); ro.repeat_items.new('GEOMETRY', 'Curves'); ri.pair_with_output(ro)
    g.set(count, ri.inputs['Iterations'])
    selected = g.node('GeometryNodeSeparateGeometry', 'Explicit membership; never proximity based')
    selected.domain = 'CURVE'; g.set(curves, selected.inputs['Geometry'])
    g.set(g.compare(g.named('st_chain_index'), ri.outputs['Iteration'], kind='INT'), selected.inputs['Selection'])
    original = selected.outputs['Selection']
    joined, valid, oriented = merge(g, original)
    size = g.node('GeometryNodeAttributeDomainSize', 'Joined controls and original Sections')
    size.component = 'CURVE'; g.set(oriented, size.inputs['Geometry'])
    last_section = g.math('SUBTRACT', size.outputs['Spline Count'], 1.)

    def meta(name, kind='FLOAT', at=0):
        return g.sample(oriented, g.named('st_sweep_'+name, kind), at, kind, 'CURVE')

    def chain(name, kind='INT'):
        return g.sample(oriented, g.named('st_chain_'+name, kind), 0, kind, 'CURVE')

    values = {name: (meta(name, kind), kind) for name, kind in (
        ('id','INT'), ('width','FLOAT'), ('offset','FLOAT'), ('rise','FLOAT'),
        ('datum','FLOAT'), ('interpolation','INT'), ('divided','BOOLEAN'), ('bundle_id','INT'))}
    for name,kind,output in (('taper','BOOLEAN','variable_dimensions'),('reach','FLOAT','dimension_reach'),
                             ('first_bound','FLOAT','dimension_first_bound'),('second_bound','FLOAT','dimension_second_bound')):
        values[output]=(g.stat(oriented,g.named('st_span_'+name,kind),'CURVE',output='Max'),kind)
    for side,at in (('start',0),('end',last_section)):
        for name in ('width','offset'):
            values[side+'_'+name]=(meta(name,at=at),'FLOAT')
    for side, at in (('start', 0), ('end', last_section)):
        reverse = g.boolean('NOT', g.sample(oriented, g.named('st_chain_forward','BOOLEAN'), at, 'BOOLEAN','CURVE'))
        opposite = 'end' if side == 'start' else 'start'
        for suffix, kind in (('', 'FLOAT_VECTOR'), ('_tangent','FLOAT_VECTOR'),
                             ('_oblique','BOOLEAN'), ('_attached','BOOLEAN'), ('_clip','FLOAT'),
                             ('_lateral','FLOAT_VECTOR'), ('_cut_axis','FLOAT_VECTOR'),
                             ('_join_shift','FLOAT'), ('_join_side','FLOAT'), ('_join_residual','FLOAT')):
            normal, backward = meta(side+suffix,kind,at), meta(opposite+suffix,kind,at)
            if suffix in ('_tangent','_lateral','_cut_axis'):
                backward = g.vector('SCALE', backward, -1.)
            values[side+suffix] = (g.switch(reverse,normal,backward,
                'VECTOR' if kind=='FLOAT_VECTOR' else kind),kind)
    length = g.node('GeometryNodeCurveLength', 'Length of all unchanged member spans')
    g.set(joined,length.inputs['Curve']); values['length']=(length.outputs['Length'],'FLOAT')
    joined_size=g.node('GeometryNodeAttributeDomainSize','Complete member control count')
    joined_size.component='CURVE';g.set(joined,joined_size.inputs['Geometry'])
    n=joined_size.outputs['Point Count'];last=g.math('SUBTRACT',n,1.)
    values['control_count']=(n,'INT')
    a,b=values['start'][0],values['end'][0]
    axis=g.vector('NORMALIZE',g.vector('SUBTRACT',b,a))
    straight=g.stat(joined,g.compare(g.vector('LENGTH',g.vector('CROSS_PRODUCT',
        g.vector('SUBTRACT',pos,a),axis)),1e-5,'LESS_EQUAL'))
    straight=g.all(straight,*(g.compare(g.vector('DISTANCE',values[s+'_tangent'][0],axis),1e-5,'LESS_EQUAL')
                             for s in ('start','end')))
    values['straight']=(straight,'BOOLEAN')
    leads=[]
    for side,i,j in (('start',0,1),('end',last,g.math('SUBTRACT',last,1.))):
        p=g.sample(joined,pos,i,'FLOAT_VECTOR');q=g.sample(joined,pos,j,'FLOAT_VECTOR')
        tangent=values[side+'_tangent'][0]
        delta=g.vector('SUBTRACT',q,p)
        distance=g.vector('LENGTH',delta)
        controls=[q,g.sample(joined,g.named('st_curve_handle_'+('right' if side=='start' else 'left'),'FLOAT_VECTOR'),i,'FLOAT_VECTOR'),
                    g.sample(joined,g.named('st_curve_handle_'+('left' if side=='start' else 'right'),'FLOAT_VECTOR'),j,'FLOAT_VECTOR')]
        aligned=g.all(*(g.compare(g.vector('LENGTH',g.vector('CROSS_PRODUCT',g.vector('SUBTRACT',v,p),tangent)),1e-5,'LESS_EQUAL')
                        for v in controls))
        leads.append(g.all(aligned,g.compare(distance,.001,'GREATER_THAN')))
        values[side+'_lead_length']=(distance,'FLOAT')
    values['terminal_leads']=(g.all(*leads),'BOOLEAN')
    valid=g.all(valid,g.compare(n,512,'LESS_EQUAL','INT'))
    failures=g.node('GeometryNodeSeparateGeometry','Preserve original Section failure reason')
    failures.domain='CURVE';g.set(oriented,failures.inputs['Geometry'])
    g.set(g.boolean('NOT',g.named('st_sweep_valid','BOOLEAN')),failures.inputs['Selection'])
    inherited=g.sample(failures.outputs['Selection'],g.named('st_sweep_diagnostic_code'),0,'INT','CURVE')
    room=g.stat(oriented,g.named('st_span_room','BOOLEAN'),'CURVE')
    code=g.switch(g.compare(inherited,0,'GREATER_THAN','INT'),g.switch(room,65,64,'INT'),inherited,'INT')
    values['valid']=(valid,'BOOLEAN');values['diagnostic_code']=(g.switch(valid,code,0,'INT'),'INT')
    values['diagnostic_position']=(meta('diagnostic_position','FLOAT_VECTOR'),'FLOAT_VECTOR')
    for name,(value,kind) in values.items():
        joined=g.store(joined,'st_sweep_'+name,value,kind,'CURVE')
    aggregate=chain('aggregate','BOOLEAN')
    result=g.switch(aggregate,original,joined,'GEOMETRY')
    for name,value,kind in (
        ('order',ri.outputs['Iteration'],'INT'),('partner',chain('partner'),'INT'),
        ('reversed',chain('reversed','BOOLEAN'),'BOOLEAN'),('inner_u',chain('inner_u','FLOAT'),'FLOAT'),
        ('make_grass',chain('owner','BOOLEAN'),'BOOLEAN'),('aggregate',aggregate,'BOOLEAN')):
        result=g.store(result,'st_sweep_'+name,value,kind,'CURVE')
    join=g.node('GeometryNodeJoinGeometry','Append complete native member')
    g.set(ri.outputs['Curves'],join.inputs['Geometry']);g.set(result,join.inputs['Geometry'])
    g.set(join.outputs['Geometry'],ro.inputs['Curves'])
    ordered=g.node('GeometryNodeSortElements','Stable compact sweep indices');ordered.domain='CURVE'
    g.set(ro.outputs['Curves'],ordered.inputs['Geometry']);g.set(g.named('st_sweep_order'),ordered.inputs['Sort Weight'])
    return g.switch(enabled,curves,ordered.outputs['Geometry'],'GEOMETRY','Old single-Section networks remain unchanged')


def section_id(g, curves, at, rank_t):
    """Piecewise constant outgoing-span ownership; never interpolate IDs."""
    from .path_station_nodes import _selected_curve
    selected,count,_length,_valid=_selected_curve(g,curves,at,'Semantic Section ownership')
    rank=g.math('MULTIPLY',rank_t,g.math('SUBTRACT',count,1.))
    segment=g.math('MINIMUM',g.math('SUBTRACT',count,2.),g.math('MAXIMUM',0.,g.math('FLOOR',rank)))
    sid=g.sample(selected,g.named('st_chain_source_section'),segment)
    aggregate=g.sample(curves,g.named('st_sweep_aggregate','BOOLEAN'),at,'BOOLEAN','CURVE')
    original=g.sample(curves,g.named('st_sweep_id'),at,'INT','CURVE')
    return g.switch(aggregate,original,sid,'INT')
